         sol='class Item:\n    def __init__(self, name, qty):\n        self.name = name\n        self.qty = qty\n\n    def __str__(self):\n        return f"{self.name} x{self.qty}"\n\ndef item_label(name, qty):\n    return str(Item(name, qty))\n',
         cases=[["potion", 3], ["key", 1], ["", 0]],
         requirements=["class"],
         hints=["__str__ must return text, not print it.", "str(item) calls item.__str__()."],
