         sol='def make_slug(title):\n    kept = "".join(ch for ch in title.lower() if ch.isalnum() or ch == " ")\n    return "-".join(kept.split())\n',
         cases=[["Hello, World!"], [""], ["  Many   spaces "], ["Top 10"], ["!!!"]],
